function check([s, k], actual, expected) {
  if (typeof actual !== 'string') return false;
  if (expected === '') return actual === '';
  if (actual.length !== s.length) return false;
  const counts = new Array(26).fill(0);
  for (const ch of s) counts[ch.charCodeAt(0) - 97]++;
  const last = new Array(26).fill(-Infinity);
  for (let i = 0; i < actual.length; i++) {
    const code = actual.charCodeAt(i) - 97;
    if (!(code >= 0 && code < 26) || --counts[code] < 0) return false;
    if (i - last[code] < k) return false;
    last[code] = i;
  }
  return true;
}

