function rearrangeString(s, k) {
  if (k <= 1) {
    return s;
  }
  const counts = new Array(26).fill(0);
  for (const ch of s) {
    counts[ch.charCodeAt(0) - 97]++;
  }

  // Max-heap of [count, letter]: more copies first, then the earlier letter.
  const heap = [];
  const before = (a, b) => a[0] > b[0] || (a[0] === b[0] && a[1] < b[1]);
  const push = (entry) => {
    heap.push(entry);
    let child = heap.length - 1;
    while (child > 0 && before(heap[child], heap[(child - 1) >> 1])) {
      const parent = (child - 1) >> 1;
      [heap[child], heap[parent]] = [heap[parent], heap[child]];
      child = parent;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length === 0) return top;
    heap[0] = last;
    let parent = 0;
    for (;;) {
      const left = 2 * parent + 1;
      let best = parent;
      if (left < heap.length && before(heap[left], heap[best])) best = left;
      if (left + 1 < heap.length && before(heap[left + 1], heap[best])) best = left + 1;
      if (best === parent) return top;
      [heap[parent], heap[best]] = [heap[best], heap[parent]];
      parent = best;
    }
  };

  for (let letter = 0; letter < 26; letter++) {
    if (counts[letter] > 0) push([counts[letter], letter]);
  }
  const result = [];
  const waiting = [];
  while (heap.length > 0) {
    const [count, letter] = pop();
    result.push(String.fromCharCode(97 + letter));
    waiting.push([count - 1, letter]);
    if (waiting.length === k) {
      const ready = waiting.shift();
      if (ready[0] > 0) push(ready);
    }
  }
  return result.length === s.length ? result.join('') : '';
}

