function rearrangeString(s, k) {
  // Exhaustive backtracking: fill positions left to right, trying every letter allowed there
  // (letters with more copies left first, so feasible inputs rarely need to back up).
  const counts = new Array(26).fill(0);
  for (const ch of s) counts[ch.charCodeAt(0) - 97]++;
  const out = [];
  const allowed = letter => counts[letter] > 0 && !out.slice(Math.max(0, out.length - k + 1)).includes(letter);
  const options = () => [...Array(26).keys()].filter(allowed).sort((a, b) => counts[b] - counts[a] || a - b);
  const candidates = [options()];
  while (out.length < s.length) {
    const list = candidates[candidates.length - 1];
    if (list.length === 0) {
      candidates.pop();
      if (out.length === 0) return '';
      counts[out.pop()]++;
      continue;
    }
    const letter = list.shift();
    out.push(letter);
    counts[letter]--;
    candidates.push(options());
  }
  return out.map(letter => String.fromCharCode(97 + letter)).join('');
}

