function generate(rand, size) {
  if (size === 'large') {
    const n = 10000;
    const alphabet = 2 + Math.floor(rand() * 25);
    const weights = Array.from({ length: alphabet }, () => 1 + rand() * 4);
    const total = weights.reduce((a, b) => a + b, 0);
    let s = '';
    for (let i = 0; i < n; i++) {
      let pick = rand() * total;
      let letter = 0;
      while (letter < alphabet - 1 && pick >= weights[letter]) pick -= weights[letter++];
      s += String.fromCharCode(97 + letter);
    }
    const k = rand() < 0.2 ? Math.floor(rand() * (n + 1)) : Math.floor(rand() * (alphabet + 2));
    return [s, k];
  }
  const n = 1 + Math.floor(rand() * 8);
  const alphabet = 1 + Math.floor(rand() * 4);
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + Math.floor(rand() * alphabet));
  const k = rand() < 0.15 ? Math.floor(rand() * (n + 1)) : Math.min(n, Math.floor(rand() * 5));
  return [s, k];
}
